#include "../engine/native/animation.hpp"
#include "../third_party/json.hpp"
#include <fstream>
#include <iostream>
#include <cstring>
#include <cmath>
int main(int argc,char** argv){const auto length=[](engine::animation::V3 v){return std::sqrt(v.x*v.x+v.y*v.y+v.z*v.z);};unsigned checks=0;const auto check=[&](bool ok,const char* text){++checks;if(!ok)throw std::runtime_error(text);};try{
  check(argc==4,"Expected tangent-morph, legacy and animated character headers");const auto asset=engine::animation::loadAsset(argv[1]),legacy=engine::animation::loadAsset(argv[2]),animated=engine::animation::loadAsset(argv[3]);check(asset->hasTangents&&!asset->morphs.empty(),"Tangent morph asset");bool found=false;for(const auto& m:asset->morphs)for(const auto& d:m.deltas){found |= length(d.tangent)>1;check(length(d.position)==0&&length(d.normal)==0,"Tangent-only targets do not displace geometry");}check(found,"Native tangent displacement retained");
  bool oldZero=true;for(const auto& m:legacy->morphs)for(const auto& d:m.deltas)oldZero &= length(d.tangent)==0;check(oldZero,"28-byte legacy records default tangent displacement to zero");bool animatedShape=false;for(const auto& c:animated->clips)if(!c.morphSamples.empty())animatedShape |= c.morphSamples.front()[0]==0&&std::abs(c.morphSamples.back()[0]-1)<.0001f;check(animatedShape,"Tangent-only animation curves survive native decoding");
  nlohmann::json header;std::ifstream(argv[1])>>header;std::ifstream stream(std::filesystem::path(argv[1]).parent_path()/"animation.bin",std::ios::binary);const std::vector<std::uint8_t> bytes((std::istreambuf_iterator<char>(stream)),{});const auto load=[&](nlohmann::json data,const std::vector<std::uint8_t>& binary){engine::determinism::Hasher h;for(auto b:binary)h.u8(b);data["binaryHash"]=h.hex();const auto text=data.dump();return engine::animation::loadAssetData({text.begin(),text.end()},binary);};const auto reject=[&](const nlohmann::json& data,const std::vector<std::uint8_t>& binary){bool rejected=false;try{load(data,binary);}catch(const engine::animation::Error&){rejected=true;}check(rejected,"Malformed tangent-morph record rejected");};
  for(int stride:{0,16,28,39,41}){auto bad=header;bad["morphs"][0]["stride"]=stride;reject(bad,bytes);}auto bad=header;bad["morphs"][0]["offset"]=0;reject(bad,bytes);auto truncated=bytes;truncated.pop_back();reject(header,truncated);const std::size_t at=header["morphs"][0]["offset"];for(float value:{std::nanf(""),11.f}){auto corrupt=bytes;std::memcpy(corrupt.data()+at+28,&value,4);reject(header,corrupt);}auto changed=bytes;float value;std::memcpy(&value,changed.data()+at+28,4);value=-value;std::memcpy(changed.data()+at+28,&value,4);check(load(header,changed)->geometryHash!=asset->geometryHash,"Tangent morph bytes participate in shared geometry identity");
  std::cout<<"{\"success\":true,\"checks\":"<<checks<<"}\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
